import assert from 'node:assert/strict';
import { checkZoomWheel, checkResultPresentation } from './diagram-presentation-ui-checks.mjs';
import { checkAnalysisResultUi } from './analysis-result-ui-checks.mjs';
import { existsSync } from 'node:fs';
import { createRequire } from 'node:module';
import path from 'node:path';

// Uses only the real local API and synthetic fixture data already generated by the caller.
export async function checkVariants({ request, base, editPath = base, summary }) {
  const ai = await request(base + '?variant=ai');
  const code = await request(base + '?variant=code');
  assert.notEqual(ai.id, code.id);
  assert.equal(ai.explanation.status, 'Semantic');
  assert.equal(code.explanation.status, 'Static');
  assert.equal((await request(base + '?variant=ai')).id, ai.id);
  assert.equal((await request(base + '?variant=code')).id, code.id);
  assert.ok(summary.aiCompleted > 0 && summary.codeCompleted >= summary.aiCompleted);
  for (const [variant, artifact] of [['ai', ai], ['code', code]]) {
    const separator = editPath.includes('?') ? '&' : '?';
    const input = { rootArtifactId: artifact.id, expectedVersion: 1, document: {
      title: artifact.ir.title, direction: artifact.ir.direction,
      nodes: artifact.ir.nodes.map((n, i) => ({ id: n.id, label: i ? n.label : `${variant} 독립 편집 확인` })),
      edges: artifact.ir.edges.map(e => ({ id: e.id, sourceId: e.sourceId, targetId: e.targetId, label: e.label, type: e.type })),
    } };
    const revision = await request(editPath + separator + 'variant=' + variant, 'POST', input, base.startsWith('/analyses/') ? 201 : 200);
    assert.equal(revision.rootArtifactId, artifact.id);
    assert.equal(revision.version, 2);
    assert.equal((await request(base + '?variant=' + variant)).mermaidDsl, artifact.mermaidDsl, 'editing must leave each generated original intact');
  }
  return { ai, code };
}

export async function checkVariantUi({ root, origin, fixture, run, requestCount }) {
  const modulePath = path.join(root, 'artifacts/ui-check/package.json');
  if (!existsSync(path.join(root, 'artifacts/ui-check/node_modules/playwright/package.json'))) return false;
  const { chromium } = createRequire(modulePath)('playwright');
  const browser = await chromium.launch({ channel: 'msedge', headless: true });
  const page = await browser.newPage({ viewport: { width: 1440, height: 1000 } });
  const before = requestCount(), errors = [];
  page.on('pageerror', e => errors.push(e.message));
  await page.route('**/*', route => new URL(route.request().url()).origin === origin ? route.continue() : route.abort());
  const group = run.results[0], view = group.views[0], source = view.pages[0];
  try {
    await page.goto(origin + '/?' + new URLSearchParams({ codeWorkspace: run.workspaceId, codeRun: run.id,
      codeScreen: 'results', codeGroup: group.groupId, codeView: view.viewId, codePage: source.id, codeVariant: 'ai' }));
    const workspace = page.locator('.code-block-workspace');
    const editors = workspace.locator('.structured-diagram-editor');
    await editors.locator('.diagram-canvas svg').waitFor();
    assert.equal(await editors.count(), 1);
    assert.equal(await workspace.getByLabel('AI/Code 함께 보기', { exact: true }).isChecked(), false);
    await workspace.getByLabel('Code 다이어그램 보기 (정적 구조)', { exact: true }).check();
    const search = workspace.getByRole('searchbox', { name: '다이어그램 이름 검색', exact: true });
    await search.fill('존재하지않는이름');
    assert.equal(await workspace.locator('[role="treeitem"]').count(), 0);
    await search.fill(source.title.replace(/^(?:AI_|Code_)/i, ''));
    assert.equal(await workspace.locator('[role="treeitem"][aria-level="4"]').count(), 2);
    await search.fill('');
    await workspace.getByLabel('AI/Code 함께 보기', { exact: true }).check();
    await editors.nth(1).locator('.diagram-canvas svg').waitFor();
    for (const editor of await editors.all()) {
      assert.doesNotMatch(await editor.locator('.diagram-canvas').innerText(), /Maximum text size|Syntax error/i);
      assert.ok(await editor.locator('.diagram-canvas svg [data-ir-kind="node"]').count() > 0, 'each canvas must render actual source nodes');
    }
    assert.equal(await editors.count(), 2);
    assert.match(await editors.nth(0).locator('.diagram-heading').innerText(), /AI_/);
    assert.match(await editors.nth(1).locator('.diagram-heading').innerText(), /Code_/);
    const first = editors.first();
    const dsl = await first.locator('details pre').textContent();
    await first.getByLabel('보기 방향', { exact: true }).selectOption('TB');
    assert.equal(await first.locator('details pre').textContent(), dsl, 'view direction leaves the saved DSL unchanged');
    await first.getByLabel('원본 기준 확대', { exact: true }).selectOption('16');
    assert.equal(await first.locator('.zoom-status').innerText(), '1600%');
    await first.getByRole('button', { name: '맞춤 보기', exact: true }).click();
    assert.match(await first.locator('.zoom-status').innerText(), /^맞춤/);
    if (view.pages.length > 1) {
      const detail = view.pages[1];
      await workspace.locator(`[data-row-id="view:${group.groupId}/${view.viewId}:${detail.id}:ai"]`).click();
      await page.waitForFunction(id => new URL(location.href).searchParams.get('codePage') === id, detail.id);
      await editors.nth(1).locator('.diagram-canvas svg [data-ir-kind="node"]').first().waitFor();
    }
    for (const width of [1440, 390]) {
      await page.setViewportSize({ width, height: 1000 });
      await workspace.locator('.diagram-comparison').screenshot({ path: path.join(fixture, `ai-code-compare-${width}.png`) });
      assert.ok(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth + 1));
    }
    await page.setViewportSize({ width: 1440, height: 1000 });
    console.log('AI/Code UI: comparison and responsive layout passed; checking reload and editing.');
    await workspace.getByLabel('AI/Code 함께 보기', { exact: true }).uncheck();
    await workspace.locator(`[data-row-id="view:${group.groupId}/${view.viewId}:${source.id}:code"]`).click();
    await page.waitForFunction(() => new URL(location.href).searchParams.get('codeVariant') === 'code');
    console.log('AI/Code UI: Code selection restored; reloading.');
    await page.reload();
    await editors.locator('.diagram-canvas svg').waitFor();
    assert.match(await editors.locator('.diagram-heading').innerText(), /Code_/);
    console.log('AI/Code UI: reload passed; opening structure editor.');
    await editors.getByRole('button', { name: '구조 편집', exact: true }).click();
    const sections = editors.locator('.structure-editor-section');
    assert.equal(await editors.locator('.structure-editor-section[open]').count(), 0);
    assert.equal(await sections.locator('input, select, option').count(), 0, 'collapsed editors do not mount hidden form controls');
    await sections.first().locator('summary').click();
    assert.equal(await sections.nth(1).locator('select, option').count(), 0, 'editing nodes must not mount every relationship endpoint option');
    assert.equal(await sections.locator('code, textarea').count(), 0, 'node IDs are hidden and labels use single-line inputs');
    await editors.getByRole('textbox', { name: '노드 1 이름', exact: true }).fill('화면에서 Code 편집');
    // Large overview layouts render asynchronously after the debounced edit preview.
    // Observe the edited SVG before clicking, rather than racing that layout pass.
    await editors.locator('.diagram-canvas [data-ir-kind="node"]').filter({ hasText: '화면에서 Code 편집' }).first().waitFor({ timeout: 60000 });
    console.log('AI/Code UI: node label changed; saving revision.');
    const [saved] = await Promise.all([
      page.waitForResponse(r => new URL(r.url()).pathname.endsWith('/edits') && r.request().method() === 'POST', { timeout: 20000 }),
      editors.getByRole('button', { name: '새 리비전 저장', exact: true }).click({ timeout: 10000 }),
    ]);
    assert.equal(saved.status(), 200);
    const revision = await saved.json();
    assert.equal(revision.rootArtifactId, source.codeArtifactId, 'the UI saves to the selected Code original');
    assert.equal(revision.diagram.ir.nodes[0].label, '화면에서 Code 편집');
    assert.equal(requestCount(), before, 'search, compare, directions, zoom, reload and edits never request generation');
    assert.deepEqual(errors, []);
    console.log('AI/Code UI: independent Code edit and immutable originals passed.');
    return true;
  } catch (error) {
    console.error(error);
    await page.screenshot({ path: path.join(fixture, 'ai-code-ui-failure.png') }).catch(() => {});
    throw error;
  } finally { await browser.close(); console.log('AI/Code UI: browser closed.'); }
}

export async function checkGitVariantUi({ root, origin, fixture, analysis, requestCount }) {
  if (!existsSync(path.join(root, 'artifacts/ui-check/node_modules/playwright/package.json'))) return false;
  const { chromium } = createRequire(path.join(root, 'artifacts/ui-check/package.json'))('playwright');
  const browser = await chromium.launch({ channel: 'msedge', headless: true });
  const page = await browser.newPage({ viewport: { width: 1440, height: 1000 } });
  const before = requestCount(), errors = [];
  page.on('pageerror', e => errors.push(e.message));
  await page.route('**/*', route => new URL(route.request().url()).origin === origin ? route.continue() : route.abort());
  try {
    await page.goto(origin);
    await page.getByRole('button', { name: 'Git 변경 분석', exact: true }).click();
    const workspace = page.locator('.analysis-workspace');
    await workspace.locator('.revision-list button').filter({ hasText: analysis.targetSha.slice(0, 10) }).first().click();
    await workspace.getByRole('button', { name: '3. 다이어그램 확인', exact: true }).click();
    const editors = workspace.locator('.structured-diagram-editor');
    await editors.first().locator('.diagram-canvas svg').waitFor();
    await workspace.getByLabel('AI/Code 함께 보기', { exact: true }).check();
    await editors.nth(1).locator('.diagram-canvas svg').waitFor();
    await workspace.locator('[role="treeitem"][aria-level="4"][data-row-id$=":code"]').first().click();
    await page.waitForFunction(() => document.querySelector('.analysis-workspace .structured-diagram-editor .diagram-heading')?.textContent.includes('Code_'));
    await editors.nth(1).locator('.diagram-canvas svg').waitFor();
    assert.match(await editors.nth(1).locator('.diagram-heading').innerText(), /AI_/);
    const tree = workspace.getByRole('tree', { name: '다이어그램 결과 트리', exact: true });
    const search = workspace.getByRole('searchbox', { name: 'Git 다이어그램 이름 검색', exact: true });
    await search.fill('이름에없는합성검색어');
    assert.equal(await tree.getByRole('treeitem').count(), 0);
    await search.fill('');
    assert.ok(await tree.getByRole('treeitem').count() > 0);
    const group = analysis.result.diagramGroups[0];
    const flow = group.views.find(v => v.document?.pages.length > 1);
    const other = group.views.find(v => v.viewId !== flow?.viewId && v.document?.pages.length);
    assert.ok(flow && other, 'the fixture exercises detail selection across different views');
    const otherPage = other.document.pages[0];
    await tree.locator(`[data-row-id="view:${group.groupId}/${other.viewId}:${otherPage.id}:ai"]`).click();
    await editors.first().locator('.diagram-canvas svg').waitFor();
    const detail = flow.document.pages.find(p => p.id !== flow.document.overviewPageId);
    await tree.locator(`[data-row-id="view:${group.groupId}/${flow.viewId}:${detail.id}:code"]`).click();
    await page.waitForFunction(id => document.querySelector('.analysis-workspace .comparison-pane')?.getAttribute('data-page-id') === id, detail.id);
    await editors.first().locator('.diagram-canvas svg').waitFor();
    assert.match(await editors.first().locator('.diagram-heading').innerText(), /Code_/);
    await workspace.getByLabel('AI/Code 함께 보기', { exact: true }).check();
    await editors.nth(1).locator('.diagram-canvas svg').waitFor();
    for (const editor of await editors.all()) {
      assert.ok(await editor.locator('.diagram-canvas svg').evaluate(svg => {
        const legend = svg.querySelector('[data-diagram-legend]');
        if (!legend) return false;
        const bounds = svg.getBoundingClientRect(), contents = legend.getBoundingClientRect();
        return contents.left >= bounds.left - 1 && contents.right <= bounds.right + 1 && contents.bottom <= bounds.bottom + 1;
      }), 'narrow Git diagrams keep the entire change legend inside the SVG');
      assert.ok(await editor.locator('.diagram-actions').evaluate(toolbar => {
        const bounds = toolbar.getBoundingClientRect();
        return [...toolbar.children].every(child => {
          const item = child.getBoundingClientRect();
          return item.left >= bounds.left - 1 && item.right <= bounds.right + 1 && getComputedStyle(child).flexShrink === '0';
        });
      }), 'comparison controls wrap without squeezing their labels');
    }
    await checkZoomWheel(page, editors.first());
    await checkResultPresentation(page, workspace, fixture, 'git');
    assert.equal(await workspace.locator('.result-group-selector,.diagram-pages,.analysis-result .diagram-type-tabs').count(), 0,
      'the result tree is the only group/type/page selector');
    await workspace.locator('.diagram-comparison').screenshot({ path: path.join(fixture, 'git-ai-code-compare.png') });
    await workspace.getByLabel('AI/Code 함께 보기', { exact: true }).uncheck();
    await checkAnalysisResultUi({ page, origin, run: fixture, status: requestCount });
    assert.equal(requestCount(), before, 'opening existing Git variants and searching must not generate');
    assert.deepEqual(errors, []);
    return true;
  } catch (error) {
    console.error(error);
    await page.screenshot({ path: path.join(fixture, 'git-ai-code-ui-failure.png') }).catch(() => {});
    throw error;
  } finally { await browser.close(); }
}
